use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [test] fn path_prefix_remapping_reverse () { { let mapping = & FilePathMapping :: new (vec ! [(path ("abc") , path ("/")) , (path ("def") , path ("."))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (reverse_map_prefix (mapping , "/hello.rs") , None) ; assert_eq ! (reverse_map_prefix (mapping , "./hello.rs") , None) ; } { let mapping = & FilePathMapping :: new (vec ! [(path ("abc") , path ("/redacted")) , (path ("def") , path ("/redacted"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (reverse_map_prefix (mapping , "/redacted/hello.rs") , None) ; } { let mapping = & FilePathMapping :: new (vec ! [(path ("abc") , path ("/redacted")) , (path ("def/ghi") , path ("/fake/dir"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: RemappedOnly ,) ; assert_eq ! (reverse_map_prefix (mapping , "/redacted/path/hello.rs") , Some (path_str ("abc/path/hello.rs"))) ; assert_eq ! (reverse_map_prefix (mapping , "/fake/dir/hello.rs") , Some (path_str ("def/ghi/hello.rs"))) ; } }
}